@sig trait AvailabilityServiceAssessment_Api {
  def id: Art.BridgeId
  def availabilityService_Id : Art.PortId
  def serviceFacts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var serviceFacts: EIT_Image_Availability_Coordinator.ServiceFacts.Type = $

  def put_serviceFacts(value : EIT_Image_Availability_Coordinator.ServiceFacts.Type) : Unit = {
    Contract(
      Modifies(serviceFacts),
      Ensures(
        serviceFacts == value
      )
    )
    Spec {
      serviceFacts = value
    }

    Art.putValue(serviceFacts_Id, EIT_Image_Availability_Coordinator.ServiceFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class AvailabilityServiceAssessment_Initialization_Api (
  val id: Art.BridgeId,
  val availabilityService_Id : Art.PortId,
  val serviceFacts_Id : Art.PortId) extends AvailabilityServiceAssessment_Api

@datatype class AvailabilityServiceAssessment_Operational_Api (
  val id: Art.BridgeId,
  val availabilityService_Id : Art.PortId,
  val serviceFacts_Id : Art.PortId) extends AvailabilityServiceAssessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var availabilityService: EIT_Image_Availability_Coordinator.ServiceObservation.Type = $

  def get_availabilityService() : Option[EIT_Image_Availability_Coordinator.ServiceObservation.Type] = {
    Contract(
      Ensures(
        Res == Some(availabilityService)
      )
    )
    val value : Option[EIT_Image_Availability_Coordinator.ServiceObservation.Type] = Art.getValue(availabilityService_Id) match {
      case Some(EIT_Image_Availability_Coordinator.ServiceObservation_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port availabilityService.  Expecting 'EIT_Image_Availability_Coordinator.ServiceObservation_Payload' but received ${v}")
        None[EIT_Image_Availability_Coordinator.ServiceObservation.Type]()
      case _ => None[EIT_Image_Availability_Coordinator.ServiceObservation.Type]()
    }
    return value
  }
}
